use tokio::sync::broadcast::{self, error::RecvError};

let (tap_tx, _rx0) = broadcast::channel::<Bytes>(1024); // ring rounds up to 2^10

// attach a tap without touching sender or receiver: one task per analyzer
tokio::spawn(inspect(tap_tx.subscribe()));

async fn inspect(mut tap: broadcast::Receiver<Bytes>) {
    let mut dropped = 0u64;
    loop {
        match tap.recv().await {
            Ok(copy) => analyze(copy).await,
            Err(RecvError::Lagged(n)) => { dropped += n; metrics::tap_drops(dropped); }
            Err(RecvError::Closed) => break,
        }
    }
}

// flow side: send() is synchronous, never blocks the primary path
match tap_tx.send(snapshot(&msg)) {          // snapshot() = deep copy or serialize
    Ok(_n) => {}  // n = subscribed receivers, NOT confirmed deliveries
    Err(_e) => {} // zero receivers: tap detached; flow unaffected
}

